import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.BjkiRu3Q.js";const g=JSON.parse('{"title":"Guía y Checklist de Capturas de Pantalla","description":"","frontmatter":{},"headers":[],"relativePath":"guia-capturas.md","filePath":"guia-capturas.md"}'),r={name:"guia-capturas.md"};function s(c,t,n,i,l,p){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="guia-y-checklist-de-capturas-de-pantalla" tabindex="-1">Guía y Checklist de Capturas de Pantalla <a class="header-anchor" href="#guia-y-checklist-de-capturas-de-pantalla" aria-label="Permalink to &quot;Guía y Checklist de Capturas de Pantalla&quot;">​</a></h1><p>Este checklist contiene el catálogo completo de capturas necesarias para documentar visualmente el sistema <strong>PayMe Panamá</strong>. Al tomar cada captura, guárdala con el nombre indicado dentro de la carpeta <code>docs/public/images/</code>.</p><hr><h2 id="capturas-del-modulo-administrador" tabindex="-1">Capturas del Módulo Administrador <a class="header-anchor" href="#capturas-del-modulo-administrador" aria-label="Permalink to &quot;Capturas del Módulo Administrador&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Archivo sugerido</th><th>URL local del sistema</th><th>Elemento / Acción a resaltar</th></tr></thead><tbody><tr><td><strong>CAP-ADM-01</strong></td><td><code>images/admin/login-admin.png</code></td><td><code>https://pyme.rsfsecure.site/login</code></td><td>Formulario de acceso con credenciales de administrador y enlace a Google.</td></tr><tr><td><strong>CAP-ADM-02</strong></td><td><code>images/admin/dashboard.png</code></td><td><code>https://pyme.rsfsecure.site/admin/dashboard</code></td><td>Tarjetas KPI de ventas, gráfico de balance y tabla de pedidos recientes.</td></tr><tr><td><strong>CAP-ADM-03</strong></td><td><code>images/admin/catalogo-lista.png</code></td><td><code>https://pyme.rsfsecure.site/admin/productos</code></td><td>Listado de productos, badges de stock y botón &quot;Nuevo Producto&quot;.</td></tr><tr><td><strong>CAP-ADM-04</strong></td><td><code>images/admin/producto-form.png</code></td><td><code>https://pyme.rsfsecure.site/admin/productos/crear</code></td><td>Formulario con pestañas: Información básica, Precios, Variantes y Galería.</td></tr><tr><td><strong>CAP-ADM-05</strong></td><td><code>images/admin/producto-modal-hd.png</code></td><td><code>https://pyme.rsfsecure.site/admin/productos</code></td><td>Modal emergente al hacer clic en una miniatura mostrando la foto en alta resolución.</td></tr><tr><td><strong>CAP-ADM-06</strong></td><td><code>images/admin/inventario-kardex.png</code></td><td><code>https://pyme.rsfsecure.site/admin/inventario</code></td><td>Tabla de movimientos (Kardex) con tipo de movimiento (Entrada/Salida/Ajuste).</td></tr><tr><td><strong>CAP-ADM-07</strong></td><td><code>images/admin/pedidos-lista.png</code></td><td><code>https://pyme.rsfsecure.site/admin/pedidos</code></td><td>Listado con badges de estado (Pendiente, En preparación, Enviado, Entregado, Cancelado).</td></tr><tr><td><strong>CAP-ADM-08</strong></td><td><code>images/admin/pedido-detalle.png</code></td><td><code>https://pyme.rsfsecure.site/admin/pedidos/1</code></td><td>Detalle del pedido, botones de cambio de estado y enlace a la factura generada.</td></tr><tr><td><strong>CAP-ADM-09</strong></td><td><code>images/admin/factura-detalle.png</code></td><td><code>https://pyme.rsfsecure.site/admin/facturas/1</code></td><td>Vista de factura con badge &quot;Emitida&quot; o &quot;Anulada&quot; y botones de descarga PDF / Ticket.</td></tr><tr><td><strong>CAP-ADM-10</strong></td><td><code>images/admin/config-zonas.png</code></td><td><code>https://pyme.rsfsecure.site/admin/zonas-envio</code></td><td>Mapeo de zonas de entrega (Ciudad de Panamá, Interior) con tarifas fijas o por peso.</td></tr></tbody></table><hr><h2 id="capturas-del-modulo-cliente-storefront" tabindex="-1">Capturas del Módulo Cliente (Storefront) <a class="header-anchor" href="#capturas-del-modulo-cliente-storefront" aria-label="Permalink to &quot;Capturas del Módulo Cliente (Storefront)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Archivo sugerido</th><th>URL local del sistema</th><th>Elemento / Acción a resaltar</th></tr></thead><tbody><tr><td><strong>CAP-CLI-01</strong></td><td><code>images/cliente/registro-2fa.png</code></td><td><code>https://pyme.rsfsecure.site/register</code></td><td>Pantalla de registro de cliente y verificación por código OTP / 2FA.</td></tr><tr><td><strong>CAP-CLI-02</strong></td><td><code>images/cliente/home-hero.png</code></td><td><code>https://pyme.rsfsecure.site/</code></td><td>Página de inicio con carrusel de promociones, marcas oficiales y productos destacados.</td></tr><tr><td><strong>CAP-CLI-03</strong></td><td><code>images/cliente/busqueda-predictiva.png</code></td><td><code>https://pyme.rsfsecure.site/</code></td><td>Barra superior con texto tecleado y dropdown de resultados sugeridos (Debounce 300ms).</td></tr><tr><td><strong>CAP-CLI-04</strong></td><td><code>images/cliente/catalogo-filtros.png</code></td><td><code>https://pyme.rsfsecure.site/catalogo</code></td><td>Catálogo público con selector de categorías, filtro de rango de precios y marcas.</td></tr><tr><td><strong>CAP-CLI-05</strong></td><td><code>images/cliente/producto-detalle.png</code></td><td><code>https://pyme.rsfsecure.site/producto/gopro...</code></td><td>Ficha del producto con galería de fotos, zoom lupa y selección de variantes.</td></tr><tr><td><strong>CAP-CLI-06</strong></td><td><code>images/cliente/carrito-drawer.png</code></td><td><code>https://pyme.rsfsecure.site/</code></td><td>Drawer lateral del carrito con resumen de ítems, subtotal y cálculo de ITBMS (7%).</td></tr><tr><td><strong>CAP-CLI-07</strong></td><td><code>images/cliente/checkout-pasos.png</code></td><td><code>https://pyme.rsfsecure.site/checkout</code></td><td>Selección de dirección de entrega, cálculo de tarifa de flete y cupones de descuento.</td></tr><tr><td><strong>CAP-CLI-08</strong></td><td><code>images/cliente/checkout-pagos.png</code></td><td><code>https://pyme.rsfsecure.site/checkout/pago</code></td><td>Pestañas de métodos de pago (Tarjeta, Yappy, Transferencia con subida de comprobante).</td></tr><tr><td><strong>CAP-CLI-09</strong></td><td><code>images/cliente/pedido-confirmado.png</code></td><td><code>https://pyme.rsfsecure.site/pedidos/.../confirmacion</code></td><td>Pantalla de confirmación con número de orden, resumen y botón para ver factura.</td></tr><tr><td><strong>CAP-CLI-10</strong></td><td><code>images/cliente/perfil-pedidos.png</code></td><td><code>https://pyme.rsfsecure.site/cliente/pedidos</code></td><td>Historial de compras del cliente con timeline del estado del envío y descarga de factura.</td></tr></tbody></table><hr><div class="tip custom-block"><p class="custom-block-title">Nota: Consejo para capturas limpias</p><ol><li>Abre tu navegador en ventana completa a resolución estándar <strong>1920×1080</strong> o <strong>1440×900</strong>.</li><li>Usa la herramienta de recorte de Windows (<code>Win + Shift + S</code>) para capturar la ventana del navegador.</li><li>Si deseas resaltar un botón o campo específico, usa un recuadro verde esmeralda (<code>#059669</code>) con grosor de 2px.</li></ol></div>',10)])])}const m=e(r,[["render",s]]);export{g as __pageData,m as default};
